/**
 * Unit tests for TokenBuffer.writeTree(TreeNode node).
 */
public class TokenBuffer_writeTree_TriageGen1Test {

    private ObjectMapper mapper;
    private TokenBuffer tokenBuffer;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        // Using the constructor with ObjectCodec as per provided documentation
        tokenBuffer = new TokenBuffer(mapper);
    }











    /**
     * Helper method to convert TokenBuffer content to a String for assertion.
     */
    private String tokenizeAndVerify(TokenBuffer buffer) throws IOException {
        // We use a dummy generator or simply use the parser to read it back
        // Since TokenBuffer is a buffer of tokens, we can use its asParser() method
        JsonParser parser = buffer.asParser(mapper);
        return mapper.readTree(parser).toString().replace(" ", ""); 
        // Note: mapper.readTree().toString() might vary slightly in formatting, 
        // but for simple structures it is reliable.
    }

    @Test
    public void testWriteTree_MultipleWrites() throws IOException {
        // Arrange
        ObjectNode node1 = mapper.createObjectNode();
        node1.put("a", 1);
        ObjectNode node2 = mapper.createObjectNode();
        node2.put("b", 2);

        // Act
        tokenBuffer.writeTree(node1);
        tokenBuffer.writeTree(node2);

        // Assert
        // TokenBuffer concatenates tokens. Writing two objects results in two JSON objects.
        // To verify, we'll use a custom approach to check token sequence.
        JsonParser parser = tokenBuffer.asParser(mapper);

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("a", parser.getCurrentName());
        assertEquals(1, parser.getIntValue());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());

        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals("b", parser.getCurrentName());
        assertEquals(2, parser.getIntValue());
        assertEquals(JsonToken.END_OBJECT, parser.nextToken());

        assertEquals(JsonToken.END_ARRAY, parser.nextToken()); // Depending on implementation details of TokenBuffer container
    }
}
